1	export type Item = {
2	  type: string;
3	  material?: string;
4	  cursed?: boolean;
5	  enchantment?: number;
6	};
7	
8	export type QuoteStep = {
9	  op: string;
10	  items: Item[];
11	};
12	
13	export type Damage = {
14	  itemType: string;
15	  amount: number;
16	};
17	
18	export type Incident = {
19	  cause: string;
20	  damages: Damage[];
21	};
22	
23	export type ClaimStep = {
24	  op: string;
25	  policy: number;
26	  incident: Incident;
27	};
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export type Customer = {
32	  yearsWithMHPCO: number;
33	};
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: Step[];
38	};
39	
40	export type QuoteResult = {
41	  premium: number;
42	};
43	
44	export type ClaimResult = {
45	  payout: number;
46	  remainingCap: number;
47	};
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export type ScenarioOutcome = {
52	  results: StepResult[];
53	};
54	
55	const PROCESSING_FEE = 5;
56	
57	const BASE_PREMIUMS: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	const FIRST_INSURANCE_PERCENT = 10;
67	
68	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
69	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
70	// intermediates to stay exact, so every percentage goes through here.
71	const PERCENT_WHOLE = 100;
72	
73	const percentOf = (amount: number, percent: number): number =>
74	  (amount * percent) / PERCENT_WHOLE;
75	
76	// Rounding always favours MHPCO: premiums round up, payouts round down.
77	const roundPremium = (amount: number): number => Math.ceil(amount);
78	
79	const basePremiumOfType = (type: string): number => BASE_PREMIUMS[type];
80	
81	const BLOCK_SIZE = 3;
82	const BLOCK_BASE_PREMIUM = 60;
83	
84	// Counts repeats among plain type names. Callers project whatever they hold
85	// (insured items, damage entries) down to the type strings they want counted,
86	// so nothing has to be dressed up as an Item just to be tallied.
87	const countOccurrences = (values: string[]): Map<string, number> => {
88	  const counts = new Map<string, number>();
89	  for (const value of values) {
90	    counts.set(value, (counts.get(value) ?? 0) + 1);
91	  }
92	  return counts;
93	};
94	
95	const typesOf = (items: Item[]): string[] => items.map((item) => item.type);
96	
97	// The counterpart of typesOf for the other side of a claim. Both feed
98	// countOccurrences, which compares insured types against damaged ones.
99	const damagedTypesOf = (damages: Damage[]): string[] =>
100	  damages.map((damage) => damage.itemType);
101	
102	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
103	
104	// A building block is exactly 3 alike components. Blocks are only offered on
105	// components, never on main items, and only at exactly 3 — 4 runes are priced
106	// per item, not as a block plus one.
107	const formsBuildingBlock = (type: string, count: number): boolean =>
108	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE;
109	
110	// A group of alike items is priced as a building block if it forms one, and
111	// per item otherwise.
112	const groupBasePremiumOf = (type: string, count: number): number =>
113	  formsBuildingBlock(type, count)
114	    ? BLOCK_BASE_PREMIUM
115	    : count * basePremiumOfType(type);
116	
117	// The policy base premium is the sum of the base premiums of each group of
118	// alike items.
119	const policyBasePremiumOf = (items: Item[]): number =>
120	  [...countOccurrences(typesOf(items))].reduce(
121	    (total, [type, count]) => total + groupBasePremiumOf(type, count),
122	    0,
123	  );
124	
125	// Item-specific surcharges are additive percentages of the affected item's OWN
126	// base premium — they never compound with each other, and never apply to the
127	// policy total.
128	const CURSE_PERCENT = 50;
129	const HIGH_ENCHANTMENT_PERCENT = 30;
130	const HIGH_ENCHANTMENT_THRESHOLD = 5;
131	
132	const isCursed = (item: Item): boolean => item.cursed === true;
133	
134	const isHighlyEnchanted = (item: Item): boolean =>
135	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
136	
137	const surchargePercentOf = (item: Item): number =>
138	  (isCursed(item) ? CURSE_PERCENT : 0) +
139	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_PERCENT : 0);
140	
141	const itemSurchargesOf = (items: Item[]): number =>
142	  items.reduce(
143	    (total, item) =>
144	      total + percentOf(basePremiumOfType(item.type), surchargePercentOf(item)),
145	    0,
146	  );
147	
148	const LOYALTY_PERCENT = 20;
149	const LOYALTY_THRESHOLD_YEARS = 2;
150	const FOLLOW_UP_CONTRACT_PERCENT = 15;
151	
152	const isLongStanding = (customer: Customer): boolean =>
153	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
154	
155	// Policy-wide modifiers are additive percentages of the policy base premium:
156	// they never compound with each other. A discount is simply a negative
157	// percentage, so surcharges and discounts sum in a single list.
158	const policyModifierPercentOf = (
159	  customer: Customer,
160	  isFollowUpContract: boolean,
161	): number =>
162	  FIRST_INSURANCE_PERCENT +
163	  (isLongStanding(customer) ? -LOYALTY_PERCENT : 0) +
164	  (isFollowUpContract ? -FOLLOW_UP_CONTRACT_PERCENT : 0);
165	
166	// Only items on the MHPCO price list can be insured.
167	const rejectIfUnknownItemType = (items: Item[]): void => {
168	  for (const item of items) {
169	    if (!(item.type in BASE_PREMIUMS)) {
170	      throw new Error(`unknown item type ${item.type}`);
171	    }
172	  }
173	};
174	
175	const processQuote = (
176	  step: QuoteStep,
177	  customer: Customer,
178	  isFollowUpContract: boolean,
179	): QuoteResult => {
180	  rejectIfUnknownItemType(step.items);
181	
182	  const basePremium = policyBasePremiumOf(step.items);
183	  const policyModifiers = percentOf(
184	    basePremium,
185	    policyModifierPercentOf(customer, isFollowUpContract),
186	  );
187	
188	  return {
189	    premium: roundPremium(
190	      basePremium +
191	        itemSurchargesOf(step.items) +
192	        policyModifiers +
193	        PROCESSING_FEE,
194	    ),
195	  };
196	};
197	
198	const INSURANCE_VALUES: Record<string, number> = {
199	  sword: 1000,
200	  amulet: 600,
201	  staff: 800,
202	  potion: 400,
203	  rune: 250,
204	  moonstone: 250,
205	};
206	
207	const DEDUCTIBLE = 100;
208	const CAP_MULTIPLIER = 2;
209	
210	// Rounding always favours MHPCO: payouts round down.
211	const roundPayout = (amount: number): number => Math.floor(amount);
212	
213	const insuranceSumOf = (items: Item[]): number =>
214	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
215	
216	// A policy is created by a quote step and accumulates claims against its cap.
217	type Policy = {
218	  items: Item[];
219	  remainingCap: number;
220	};
221	
222	// The cap is twice the insurance sum of the covered items. It is derived from
223	// the UNMODIFIED insurance values: neither premium surcharges nor the building
224	// block discount move it, so it is computed from the items alone.
225	const openPolicyFor = (items: Item[]): Policy => ({
226	  items,
227	  remainingCap: CAP_MULTIPLIER * insuranceSumOf(items),
228	});
229	
230	const isClaimStep = (step: Step): step is ClaimStep => step.op === "claim";
231	
232	// Distinct from HIGH_ENCHANTMENT_THRESHOLD (5) above, which bands an item as
233	// risky enough to carry a premium SURCHARGE. This higher bar marks an item as
234	// volatile: MHPCO caps its exposure by reimbursing only half the damage. Two
235	// unrelated rules that happen to both read the enchantment level — they are
236	// free to move independently, so they get independent names and constants.
237	const VOLATILE_ENCHANTMENT_THRESHOLD = 8;
238	const VOLATILE_REIMBURSEMENT_PERCENT = 50;
239	
240	const isVolatilelyEnchanted = (item: Item): boolean =>
241	  (item.enchantment ?? 0) >= VOLATILE_ENCHANTMENT_THRESHOLD;
242	
243	const DRAGON_MATERIAL = "dragon";
244	const FULL_REIMBURSEMENT_PERCENT = 100;
245	
246	const isDragonMaterial = (item: Item): boolean =>
247	  item.material === DRAGON_MATERIAL;
248	
249	// Special clauses in precedence order. Dragon material is fully reimbursed, but
250	// where an item is also volatilely enchanted the 50 % rule wins.
251	//
252	// NOTE: the dragon branch is currently indistinguishable from the default —
253	// full reimbursement is what an ordinary item gets anyway, and every spec
254	// example pairing dragon material with enchantment >= 8 is decided by the
255	// volatile rule above it. No test constrains this branch. It is written out
256	// because the spec states it as a rule, so that it is represented rather than
257	// accidental if the default ever stops being full reimbursement.
258	const reimbursementPercentFor = (item: Item): number => {
259	  if (isVolatilelyEnchanted(item)) return VOLATILE_REIMBURSEMENT_PERCENT;
260	  if (isDragonMaterial(item)) return FULL_REIMBURSEMENT_PERCENT;
261	  return FULL_REIMBURSEMENT_PERCENT;
262	};
263	
264	// The deductible is withheld once per damaged item, so it is subtracted per
265	// damage entry rather than once from the incident total. Special clauses reduce
266	// the reimbursement first; the deductible always comes last.
267	const netPayableFor = (damage: Damage, item: Item): number =>
268	  percentOf(damage.amount, reimbursementPercentFor(item)) - DEDUCTIBLE;
269	
270	// The insured item a damage entry refers to. The cast holds only while every
271	// damage entry is guaranteed to name an insured type; the "claim for an item
272	// not part of the policy" test will force this to return undefined honestly.
273	const insuredItemFor = (damage: Damage, policy: Policy): Item =>
274	  policy.items.find((item) => item.type === damage.itemType) as Item;
275	
276	// Named for what it sums: each entry has already had its deductible withheld
277	// by netPayableFor, so this is the payable total, not the reimbursement total.
278	const totalPayableFor = (incident: Incident, policy: Policy): number =>
279	  incident.damages.reduce(
280	    (total, damage) =>
281	      total + netPayableFor(damage, insuredItemFor(damage, policy)),
282	    0,
283	  );
284	
285	// A policy covers a fixed set of items, so a claim cannot report more damaged
286	// items of a type than the policy actually covers.
287	const rejectIfOverclaimed = (incident: Incident, policy: Policy): void => {
288	  const insured = countOccurrences(typesOf(policy.items));
289	  const damaged = countOccurrences(damagedTypesOf(incident.damages));
290	
291	  for (const [type, damagedCount] of damaged) {
292	    const insuredCount = insured.get(type) ?? 0;
293	    if (damagedCount > insuredCount) {
294	      throw new Error(
295	        `claim reports ${damagedCount} damaged ${type}(s) but the policy covers ${insuredCount}`,
296	      );
297	    }
298	  }
299	};
300	
301	const rejectIfNegativeDamage = (incident: Incident): void => {
302	  for (const damage of incident.damages) {
303	    if (damage.amount < 0) {
304	      throw new Error(
305	        `damage to ${damage.itemType} has a negative amount ${damage.amount}`,
306	      );
307	    }
308	  }
309	};
310	
311	// Pure: reports what the claim pays and what the cap would be left at. The
312	// caller owns writing the depleted cap back to the policy.
313	const processClaim = (step: ClaimStep, policy: Policy): ClaimResult => {
314	  rejectIfNegativeDamage(step.incident);
315	  rejectIfOverclaimed(step.incident, policy);
316	
317	  const uncappedPayout = roundPayout(totalPayableFor(step.incident, policy));
318	  // The total payout per policy is capped; a claim gets whatever cap is left.
319	  const payout = Math.min(uncappedPayout, policy.remainingCap);
320	
321	  return { payout, remainingCap: policy.remainingCap - payout };
322	};
323	
324	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
325	  const policies = new Map<number, Policy>();
326	  let quotesSoFar = 0;
327	
328	  const results = scenario.steps.map((step, index): StepResult => {
329	    if (isClaimStep(step)) {
330	      const policy = policies.get(step.policy) as Policy;
331	      const result = processClaim(step, policy);
332	      // Claims deplete the cap for every later claim against this policy.
333	      policy.remainingCap = result.remainingCap;
334	      return result;
335	    }
336	
337	    const result = processQuote(step, scenario.customer, quotesSoFar > 0);
338	    quotesSoFar += 1;
339	    policies.set(index, openPolicyFor(step.items));
340	    return result;
341	  });
342	
343	  return { results };
344	};
345

